package school.chacademia.housing.presence;
import java.util.*;import java.io.*;import java.net.*;import java.lang.reflect.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
import com.velocitypowered.api.proxy.*;import com.velocitypowered.api.proxy.server.ServerInfo;import com.velocitypowered.api.event.connection.PluginMessageEvent;
class HousingPresencePluginTest{
 interface Calls{Object call(String n,Object[] a);}
 @SuppressWarnings("unchecked")static <T>T mock(Class<T>t,Calls c){return(T)java.lang.reflect.Proxy.newProxyInstance(t.getClassLoader(),new Class[]{t},(p,m,a)->{if(m.getName().equals("equals"))return p==a[0];if(m.getName().equals("hashCode"))return System.identityHashCode(p);if(m.getName().equals("toString"))return t.getSimpleName();return c.call(m.getName(),a==null?new Object[0]:a);});}
 final List<Person> people=new ArrayList<>();final UUID nonce=UUID.randomUUID();
 class Person{final UUID id=UUID.randomUUID();final Player player;ServerConnection source;final List<byte[]>frames=new ArrayList<>();Person(String server){player=mock(Player.class,(n,a)->switch(n){case"getUniqueId"->id;case"getCurrentServer"->Optional.ofNullable(source);default->null;});move(server);people.add(this);}void move(String server){source=mock(ServerConnection.class,(n,a)->switch(n){case"getPlayer"->player;case"getServerInfo"->new ServerInfo(server,new InetSocketAddress("localhost",25566));case"sendPluginMessage"->{frames.add((byte[])a[1]);yield true;}default->null;});}}
 HousingPresencePlugin plugin(){var proxy=mock(ProxyServer.class,(n,a)->n.equals("getAllPlayers")?people.stream().map(p->p.player).toList():null);return new HousingPresencePlugin(proxy);}
 byte[] request()throws Exception{var b=new ByteArrayOutputStream();var o=new DataOutputStream(b);o.writeByte(1);o.writeLong(nonce.getMostSignificantBits());o.writeLong(nonce.getLeastSignificantBits());return b.toByteArray();}
 @Test void realHandlerReturnsGlobalUuidsInBoundedChunksWithoutNonNetworkOrDuplicates()throws Exception{var actor=new Person("school");new Person("wild");new Person("arena");new Person("limbo");for(int i=0;i<1050;i++)new Person(i%2==0?"wild":"arena");var event=new PluginMessageEvent(actor.source,actor.player,HousingPresencePlugin.CHANNEL,request());plugin().message(event);assertEquals(PluginMessageEvent.ForwardResult.handled(),event.getResult());assertEquals(3,actor.frames.size());var ids=new HashSet<UUID>();for(int frame=0;frame<actor.frames.size();frame++){var bytes=actor.frames.get(frame);assertTrue(bytes.length<9000);try(var in=new DataInputStream(new ByteArrayInputStream(bytes))){assertEquals(1,in.readUnsignedByte());assertEquals(nonce,new UUID(in.readLong(),in.readLong()));assertEquals(frame==actor.frames.size()-1,in.readBoolean());int n=in.readUnsignedShort();assertTrue(n<=512);for(int i=0;i<n;i++)assertTrue(ids.add(new UUID(in.readLong(),in.readLong())));assertEquals(0,in.available());}}assertEquals(1053,ids.size());assertEquals(1053,people.stream().filter(p->p.source.getServerInfo().getName().matches("school|wild|arena")).count());}
 @Test void clientAndStaleBackendCannotSupplyOrRequestARoster()throws Exception{var actor=new Person("school");var plugin=plugin();var forged=new PluginMessageEvent(actor.player,actor.source,HousingPresencePlugin.CHANNEL,request());plugin.message(forged);assertEquals(PluginMessageEvent.ForwardResult.handled(),forged.getResult());assertTrue(actor.frames.isEmpty());var old=actor.source;actor.move("wild");plugin.message(new PluginMessageEvent(old,actor.player,HousingPresencePlugin.CHANNEL,request()));assertTrue(actor.frames.isEmpty());}
}
